import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ChevronLeft,
  Plus,
  LayoutGrid,
  List as ListIcon,
  BarChart3,
  Calendar,
  Users,
  DollarSign,
  TrendingUp,
  CheckCircle,
  MoreVertical,
} from "lucide-react";
import { DashboardHeader } from "../components/dashboard/DashboardHeader";
import { Button } from "../components/ui/button";
import { Badge } from "../components/ui/badge";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "../components/ui/tabs";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../components/ui/card";
import { Progress } from "../components/ui/progress";
import { KanbanBoard } from "../components/kanban/KanbanBoard";
import { TaskDetailModal } from "../components/kanban/TaskDetailModal";
import { projectService } from "../services/projectService";
import { formatDate, formatCurrency } from "../utils/formatters";
import Swal from "sweetalert2";

const ProjectDetailPage = () => {
  const { projectId } = useParams();
  const navigate = useNavigate();
  const [project, setProject] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("board");
  const [selectedTask, setSelectedTask] = useState(null);
  const [showTaskModal, setShowTaskModal] = useState(false);

  useEffect(() => {
    loadProject();
  }, [projectId]);

  const loadProject = async () => {
    try {
      setLoading(true);
      const data = await projectService.getById(projectId);
      setProject(data);
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "Error al Cargar Proyecto",
        text: error.response?.data?.detail || "No se pudo cargar el proyecto",
        confirmButtonColor: "#dc2626",
        timer: 3000,
      });
      navigate("/projects");
    } finally {
      setLoading(false);
    }
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setShowTaskModal(true);
  };

  const handleAddTask = async () => {
    const { value: formValues } = await Swal.fire({
      title: "Nueva Tarea",
      html: `
        <input id="swal-input1" class="swal2-input" placeholder="Título de la tarea">
        <textarea id="swal-input2" class="swal2-textarea" placeholder="Descripción (opcional)"></textarea>
      `,
      focusConfirm: false,
      showCancelButton: true,
      confirmButtonColor: "#16a34a",
      cancelButtonColor: "#6b7280",
      confirmButtonText: "Crear Tarea",
      cancelButtonText: "Cancelar",
      preConfirm: () => {
        const title = document.getElementById("swal-input1").value;
        const description = document.getElementById("swal-input2").value;

        if (!title) {
          Swal.showValidationMessage("El título es requerido");
          return false;
        }

        return { title, description };
      },
    });

    if (formValues) {
      try {
        // ✅ CRÍTICO: Usar String ID que coincida con el modelo
        const newTask = {
          _id: Date.now().toString(), // String ID compatible con modelo
          title: formValues.title,
          description: formValues.description || "",
          status: "todo",
          priority: "medium",
          subtasks: [],
          tags: [],
          attachments: [],
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };

        // Actualizar estado local primero (UX optimista)
        const updatedTasks = [...(project.tasks || []), newTask];
        setProject({ ...project, tasks: updatedTasks });

        // Guardar en backend
        const savedProject = await projectService.update(projectId, {
          tasks: updatedTasks,
        });

        // Actualizar con respuesta del servidor
        setProject(savedProject);

        Swal.fire({
          icon: "success",
          title: "Tarea Creada",
          toast: true,
          position: "top-end",
          showConfirmButton: false,
          timer: 2000,
          timerProgressBar: true,
        });
      } catch (error) {
        console.error("Error creating task:", error);
        // Revertir estado local si falla
        loadProject();
        Swal.fire({
          icon: "error",
          title: "Error",
          text: error.response?.data?.detail || "No se pudo crear la tarea",
          confirmButtonColor: "#dc2626",
        });
      }
    }
  };

  const handleTaskMove = async (taskId, newStatus) => {
    if (!project || !project.tasks) return;

    try {
      // Actualizar estado local inmediatamente para UX fluida
      const updatedTasks = project.tasks.map((task) =>
        task._id === taskId
          ? { ...task, status: newStatus, updated_at: new Date().toISOString() }
          : task
      );

      setProject({ ...project, tasks: updatedTasks });

      // Guardar en backend
      const savedProject = await projectService.update(projectId, {
        tasks: updatedTasks,
      });

      // Actualizar con la respuesta del servidor
      setProject(savedProject);

      Swal.fire({
        icon: "success",
        title: "Tarea Actualizada",
        toast: true,
        position: "top-end",
        showConfirmButton: false,
        timer: 1500,
        timerProgressBar: true,
      });
    } catch (error) {
      console.error("Error moving task:", error);
      // Revertir cambio local si falla
      loadProject();
      Swal.fire({
        icon: "error",
        title: "Error",
        text: error.response?.data?.detail || "No se pudo mover la tarea",
        confirmButtonColor: "#dc2626",
      });
    }
  };

  const handleTaskUpdate = async (updatedTask) => {
    if (!project || !project.tasks) return;

    try {
      const updatedTasks = project.tasks.map((task) =>
        task._id === updatedTask._id
          ? { ...updatedTask, updated_at: new Date().toISOString() }
          : task
      );

      // Actualizar estado local
      setProject({ ...project, tasks: updatedTasks });

      // Guardar en backend
      const savedProject = await projectService.update(projectId, {
        tasks: updatedTasks,
      });

      setProject(savedProject);
      setShowTaskModal(false);

      Swal.fire({
        icon: "success",
        title: "Tarea Actualizada",
        toast: true,
        position: "top-end",
        showConfirmButton: false,
        timer: 2000,
        timerProgressBar: true,
      });
    } catch (error) {
      console.error("Error updating task:", error);
      loadProject();
      throw error;
    }
  };

  const handleTaskDelete = async (taskId) => {
    if (!project || !project.tasks) return;

    try {
      const updatedTasks = project.tasks.filter((task) => task._id !== taskId);

      setProject({ ...project, tasks: updatedTasks });

      const savedProject = await projectService.update(projectId, {
        tasks: updatedTasks,
      });

      setProject(savedProject);

      Swal.fire({
        icon: "success",
        title: "Tarea Eliminada",
        toast: true,
        position: "top-end",
        showConfirmButton: false,
        timer: 2000,
        timerProgressBar: true,
      });
    } catch (error) {
      console.error("Error deleting task:", error);
      loadProject();
      throw error;
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <DashboardHeader />
        <div className="flex items-center justify-center h-96">
          <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-green-500"></div>
        </div>
      </div>
    );
  }

  if (!project) {
    return null;
  }

  const completedTasks =
    project.tasks?.filter((t) => t.status === "completed").length || 0;
  const totalTasks = project.tasks?.length || 0;
  const taskProgress = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  return (
    <div className="min-h-screen bg-gray-50">
      <DashboardHeader />

      {/* Project Header */}
      <div className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center gap-4 mb-4">
            <Button
              onClick={() => navigate("/dashboard")}
              variant="ghost"
              size="sm"
            >
              <Home className="w-4 h-4 mr-2" />
              Dashboard
            </Button>
            <Button
              onClick={() => navigate("/projects")}
              variant="ghost"
              size="sm"
            >
              <ChevronLeft className="w-4 h-4 mr-2" />
              Proyectos
            </Button>
          </div>

          <div className="flex items-start justify-between mb-4">
            <div className="flex-1">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">
                {project.project_name}
              </h1>
              <p className="text-gray-600">{project.client_id?.company_name}</p>
            </div>

            <div className="flex items-center gap-2">
              <Button
                onClick={handleAddTask}
                className="bg-green-600 hover:bg-green-700"
              >
                <Plus className="w-4 h-4 mr-2" />
                Nueva Tarea
              </Button>
              <Button variant="outline" size="icon">
                <MoreVertical className="w-4 h-4" />
              </Button>
            </div>
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-sm text-gray-600 mb-1">
                  <Calendar className="w-4 h-4" />
                  <span>Fecha límite</span>
                </div>
                <p className="font-semibold text-gray-900">
                  {formatDate(project.estimated_end_date)}
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-sm text-gray-600 mb-1">
                  <DollarSign className="w-4 h-4" />
                  <span>Presupuesto</span>
                </div>
                <p className="font-semibold text-gray-900">
                  {formatCurrency(project.budget)}
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-sm text-gray-600 mb-1">
                  <TrendingUp className="w-4 h-4" />
                  <span>Progreso</span>
                </div>
                <p className="font-semibold text-gray-900">
                  {Math.round(taskProgress)}%
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-sm text-gray-600 mb-1">
                  <Users className="w-4 h-4" />
                  <span>Equipo</span>
                </div>
                <p className="font-semibold text-gray-900">
                  {project.assigned_to?.length || 0} miembros
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Progress Bar */}
          <div className="mb-4">
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-medium text-gray-700">
                Progreso del Proyecto
              </span>
              <span className="text-sm text-gray-600">
                {completedTasks} de {totalTasks} tareas completadas
              </span>
            </div>
            <Progress value={taskProgress} className="h-2" />
          </div>

          {/* Tabs Navigation */}
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="border-b-0">
              <TabsTrigger value="board">
                <LayoutGrid className="w-4 h-4 mr-2" />
                Board
              </TabsTrigger>
              <TabsTrigger value="list">
                <ListIcon className="w-4 h-4 mr-2" />
                Lista
              </TabsTrigger>
              <TabsTrigger value="team">
                <Users className="w-4 h-4 mr-2" />
                Equipo
              </TabsTrigger>
              <TabsTrigger value="overview">
                <BarChart3 className="w-4 h-4 mr-2" />
                Resumen
              </TabsTrigger>
            </TabsList>
          </Tabs>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <Tabs value={activeTab}>
          {/* Board View */}
          <TabsContent value="board" className="mt-0">
            <KanbanBoard
              tasks={project.tasks || []}
              onTaskClick={handleTaskClick}
              onAddTask={handleAddTask}
              onTaskMove={handleTaskMove}
            />
          </TabsContent>

          {/* List View */}
          <TabsContent value="list" className="mt-0">
            <Card>
              <CardContent className="p-0">
                {project.tasks && project.tasks.length > 0 ? (
                  <div className="divide-y">
                    {project.tasks.map((task) => (
                      <div
                        key={task._id}
                        onClick={() => handleTaskClick(task)}
                        className="p-4 hover:bg-gray-50 cursor-pointer"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-3 flex-1">
                            <input
                              type="checkbox"
                              checked={task.status === "completed"}
                              onChange={(e) => {
                                e.stopPropagation();
                                handleTaskMove(
                                  task._id,
                                  e.target.checked ? "completed" : "todo"
                                );
                              }}
                              className="w-4 h-4 text-green-600 rounded focus:ring-green-500"
                            />
                            <div className="flex-1">
                              <h4
                                className={`font-medium ${
                                  task.status === "completed"
                                    ? "line-through text-gray-400"
                                    : "text-gray-900"
                                }`}
                              >
                                {task.title}
                              </h4>
                              {task.description && (
                                <p className="text-sm text-gray-500 mt-1">
                                  {task.description}
                                </p>
                              )}
                            </div>
                          </div>
                          <div className="flex items-center gap-3">
                            {task.due_date && (
                              <span className="text-xs text-gray-500">
                                {formatDate(task.due_date)}
                              </span>
                            )}
                            <Badge variant="outline" className="text-xs">
                              {task.priority}
                            </Badge>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <CheckCircle className="w-12 h-12 mx-auto text-gray-400 mb-3" />
                    <p className="text-gray-600">No hay tareas aún</p>
                    <Button
                      onClick={handleAddTask}
                      className="mt-4"
                      variant="outline"
                    >
                      <Plus className="w-4 h-4 mr-2" />
                      Crear primera tarea
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Team View */}
          <TabsContent value="team" className="mt-0">
            <Card>
              <CardHeader>
                <CardTitle>Equipo del Proyecto</CardTitle>
              </CardHeader>
              <CardContent>
                {project.assigned_to && project.assigned_to.length > 0 ? (
                  <div className="space-y-4">
                    {project.assigned_to.map((member) => (
                      <div
                        key={member._id}
                        className="flex items-center justify-between p-4 bg-gray-50 rounded-lg"
                      >
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-full bg-green-100 flex items-center justify-center text-lg font-semibold text-green-700">
                            {member.full_name?.charAt(0)}
                          </div>
                          <div>
                            <p className="font-semibold text-gray-900">
                              {member.full_name}
                            </p>
                            <p className="text-sm text-gray-500">
                              {member.email}
                            </p>
                          </div>
                        </div>
                        <Badge variant="outline">
                          {member.role || "member"}
                        </Badge>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8">
                    <Users className="w-12 h-12 mx-auto text-gray-400 mb-3" />
                    <p className="text-gray-600">No hay miembros asignados</p>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Overview View */}
          <TabsContent value="overview" className="mt-0">
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>Descripción del Proyecto</CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-gray-700">{project.description}</p>
                </CardContent>
              </Card>

              <div className="grid md:grid-cols-2 gap-6">
                <Card>
                  <CardHeader>
                    <CardTitle>Detalles</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div>
                      <span className="text-sm text-gray-600">Tipo:</span>
                      <p className="font-semibold capitalize">
                        {project.project_type}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600">Estado:</span>
                      <p className="font-semibold capitalize">
                        {project.status}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600">Prioridad:</span>
                      <p className="font-semibold capitalize">
                        {project.priority}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600">
                        Fecha de inicio:
                      </span>
                      <p className="font-semibold">
                        {formatDate(project.start_date)}
                      </p>
                    </div>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle>Estadísticas</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div>
                      <span className="text-sm text-gray-600">
                        Tareas completadas:
                      </span>
                      <p className="font-semibold">
                        {completedTasks} de {totalTasks}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600">Progreso:</span>
                      <p className="font-semibold">
                        {Math.round(taskProgress)}%
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600">
                        Miembros del equipo:
                      </span>
                      <p className="font-semibold">
                        {project.assigned_to?.length || 0}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600">
                        Presupuesto:
                      </span>
                      <p className="font-semibold">
                        {formatCurrency(project.budget)}
                      </p>
                    </div>
                  </CardContent>
                </Card>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </div>

      {/* Task Detail Modal */}
      <TaskDetailModal
        isOpen={showTaskModal}
        onClose={() => {
          setShowTaskModal(false);
          setSelectedTask(null);
        }}
        task={selectedTask}
        onUpdate={handleTaskUpdate}
        onDelete={handleTaskDelete}
        teamMembers={project.assigned_to || []}
      />
    </div>
  );
};

export default ProjectDetailPage;
